import React, { PropsWithChildren } from 'react';

import { useNavigateSpinButton } from './hooks/useNavigateSpinButton.js';
import { useValueOverflow } from './hooks/useValueOverflow.js';
import { SpinButtonGroupSeparator } from './SpinButtonGroupSeparator.js';
import type { _SpinButtonGroupProps } from './types.js';
import { _NumberSpinButton } from '../number-spin-button/NumberSpinButton.js';
import { _TextSpinButton } from '../text-spin-button/TextSpinButton.js';

const SpinButtonGroup = ({
  children,
  valueOverflow = false,
  ...remainingProps
}: PropsWithChildren<_SpinButtonGroupProps>) => {
  const { clonedChildren, spinButtonRefs, triggerRefs } = useValueOverflow(
    children,
    valueOverflow,
  );

  const { keyDownHandler } = useNavigateSpinButton(spinButtonRefs, triggerRefs);

  return (
    <span {...remainingProps} onKeyDown={keyDownHandler}>
      {clonedChildren}
    </span>
  );
};

/**
 * @internal
 * Use the _SpinButtonGroup to combine text and number spinbuttons and provide ootb navigation between them.
 */
export const _SpinButtonGroup = Object.assign(SpinButtonGroup, {
  Number: _NumberSpinButton,
  Text: _TextSpinButton,
  Separator: SpinButtonGroupSeparator,
});

(
  _SpinButtonGroup as typeof _SpinButtonGroup & { displayName: string }
).displayName = '_SpinButtonGroup';
